INSERT INTO documents(collection,doc_id,data) VALUES ('siteArticles','guides:wow-android-winlator-guide','{"kind":"guides","slug":"wow-android-winlator-guide","title":"Як запустити WoW 3.3.5a на Android: Повний Гайд Winlator","description":"Грайте в World of Warcraft на смартфоні! Налаштування Winlator, драйвер Turnip, оптимізація Config.wtf для 60 FPS та керування.","body":"Запуск повноцінної версії **World of Warcraft** на телефоні став реальністю завдяки емулятору **Winlator**. У цьому гайді ми розглянемо, як налаштувати емулятор, оптимізувати конфігурацію гри та отримати стабільні 60 FPS навіть у рейдах.\n\n---\n\n## 📋 Що знадобиться\n\nПеред початком переконайтеся, що у вас є:\n\n1.  **Смартфон Android:** Бажано з процесором **Snapdragon** (серії 8 Gen 1/2/3) для кращої сумісності драйверів Turnip.\n2.  **Winlator:** Остання версія з [GitHub репозиторія](https://github.com/brunodev85/winlator/releases).\n3.  **Клієнт WoW:** Вже встановлена та оновлена гра на ПК (версія 3.3.5a, Dragonflight або інша).\n\n---\n\n## 🚀 Крок 1: Підготовка файлів\n\n> ⚠️ **Важливо:** Не намагайтеся завантажити гру через Battle.net лаунчер на телефоні — це займе вічність і може викликати помилки.\n\n1.  Скопіюйте папку з грою (наприклад, `World of Warcraft`) з вашого ПК на телефон через USB-кабель.\n2.  **Рекомендований шлях:** `Download/WoW` (так її легше знайти всередині емулятора на диску D:).\n\n---\n\n## ⚙️ Крок 2: Налаштування Winlator\n\n1.  Встановіть `.apk` файл Winlator та запустіть його. Дочекайтеся розпакування системних файлів (OBB).\n2.  Натисніть **\"+\"** (плюс) у кутку, щоб створити новий контейнер.\n3.  Виставте наступні налаштування:\n\n    * **Screen Size:** `1280x720` (рекомендується) або `800x600` (для слабких девайсів).\n    * **Graphics Driver:** `Turnip (Zink)` — це критично для чіпів Snapdragon.\n    * **DXVK:** `DXVK 1.10.3` або `2.2` (експериментуйте, якщо гра вилітає при запуску).\n    * **GPU Name:** `GTX 1070` (або аналогічну, щоб гра дозволила вищі налаштування текстур).\n    * **Video Memory Size:** `2048MB` або `4096MB`.\n\n---\n\n## 🛠️ Крок 3: Оптимізація файлу конфігурації (Важливо!)\n\nДля максимальної продуктивності та стабільності ми рекомендуємо **не налаштовувати графіку в грі**, а вручну прописати готовий конфіг. Це вимкне зайві шейдери, тіні та ефекти, які \"душать\" мобільний процесор.\n\n1.  Зайдіть у папку з грою на телефоні (через будь-який файловий менеджер).\n2.  Перейдіть у папку `WTF`.\n3.  Відкрийте файл `Config.wtf` як текст (або створіть його, якщо немає).\n4.  **Повністю замініть** його вміст на цей код:\n\n<pre style=\"background: #2b2b2b; color: #f8f8f2; padding: 15px; border-radius: 5px; overflow-x: auto; font-family: monospace;\">\nSET locale \"enUS\"\nSET accounttype \"LK\"\nSET readTOS \"1\"\nSET readEULA \"1\"\nSET gxResolution \"1280x720\"\nSET gxMaximize \"1\"\nSET vsync \"0\"\nSET maxFPS \"60\"\nSET maxFPSBk \"8\"\nSET Gamma \"1.000000\"\nSET projectedTextures \"1\"\nSET shadowLevel \"0\"\nSET farclip \"500\"\nSET textureFilteringMode \"0\"\nSET componentTextureLevel \"0\"\nSET groundEffectDist \"70\"\nSET weatherDensity \"3\"\nSET particleDensity \"0.3\"\nSET rippleDetail \"0\"\nSET reflectionMode \"0\"\nSET pixelShaders \"1\"\nSET ffxGlow \"0\"\nSET ffxDeath \"0\"\nSET uiScale \"0.85\"\nSET useUiScale \"1\"\nSET showToolsUI \"1\"\nSET gameTip \"4\"\nSET Sound_OutputDriverName \"System Default\"\nSET Sound_MusicVolume \"0.20000000298023\"\nSET Sound_AmbienceVolume \"0.30000001192093\"\nSET gxCursor \"0\"\nSET gxTextureCacheSize \"128\"\nSET timingMethod \"1\"\nSET hwDetect \"0\"\nSET checkAddonVersion \"0\"\nSET mouseSpeed \"1\"\nSET gxRefresh \"60\"\nSET gxMultisampleQuality \"0.000000\"\nSET videoOptionsVersion \"3\"\nSET movie \"0\"\n</pre>\n\n---\n\n## 🎮 Крок 4: Запуск гри\n\n1.  Поверніться у головне меню **Winlator**.\n2.  Натисніть на меню (три крапки) біля вашого контейнера та оберіть **Run**.\n3.  У вікні Windows, що відкрилося, перейдіть на диск **`D:`** (це ваша папка `Downloads` на телефоні).\n4.  Знайдіть папку `WoW`.\n5.  Запускайте файл **`Wow.exe`** подвійним кліком.\n\n> 🚫 **Важливо:** Не використовуйте `Launcher.exe`, оскільки він може намагатися оновити гру або з''єднатися з Battle.net, що призведе до помилок та вильотів.\n\n---\n\n## 💡 Поради щодо керування\n\nГрати на сенсорному екрані без попереднього налаштування незручно. Щоб зробити геймплей комфортним:\n\n* Відкрийте меню емулятора (свайп \"Назад\" на телефоні) та виберіть **Input Controls**.\n* **Створіть віртуальні кнопки** для найважливіших дій: `Tab` (ціль), `Space` (стрибок), `1`, `2`, `3`, `4`, `5` (здібності).\n* **Додайте кнопки інтерфейсу:** `M` (карта), `B` (сумки), `C` (персонаж).\n* У налаштуваннях **Input** виберіть режим миші **\"RTS\"** — це дозволить керувати камерою та курсором подібно до тачпада ноутбука, що ідеально підходить для WoW.\n\n---\n\n> **📱 Примітка для власників Mali (Exynos, MediaTek, Tensor)**\n> \n> Якщо у вас смартфон на базі чіпів від **Google (Tensor)**, **Samsung (Exynos)** або **MediaTek (Dimensity)** — ваш графічний прискорювач **Mali**.\n> \n> На жаль, швидкий драйвер **Turnip** з ними не працює. Вам доведеться вибрати драйвер **VirGL** у налаштуваннях контейнера. Будьте готові до того, що продуктивність буде значно нижчою, і можливі графічні артефакти.","author":"Sebas","date":"2026-01-24","last_modified_at":"2026-01-25","categories":"Android, Гайд","tags":"WoW, Winlator, Emulation, 3.3.5a, Optimization","image":"/assets/img-content/wow-winlator-cover.webp","revision":1,"updated_at":"2026-10-15T00:00:00.000Z"}'::jsonb) ON CONFLICT (collection,doc_id) DO NOTHING;
INSERT INTO documents(collection,doc_id,data) VALUES ('siteArticles','guides:midnight-4-renown-items-246-ilvl','{"kind":"guides","slug":"midnight-4-renown-items-246-ilvl","title":"WoW: Midnight — 4 Renown-предмети 246 ilvl","description":"Повний і зрозумілий гайд по 4 Renown-предметах 246 ilvl у World of Warcraft: Midnight. Розбір квестів, активностей та нагород.","body":"У доповненні **Midnight** є чотири надзвичайно корисні **Renown-нагороди рівня Champion (1/6) 246 ilvl**, які прив’язані до чотирьох основних фракцій:\n\n* **The Singularity** — тринкет\n* **The Hara''ti** — пояс\n* **Silvermoon Court** — шолом\n* **Amani Tribe** — намисто\n\nГоловна перевага цих речей — відсутність рандому. Схема отримання проста: викачуєш потрібний **Renown**, береш **квест**, закриваєш пов’язану з ним **активність** і гарантовано забираєш свій **246 Champion piece**.\n\n---\n\n## 📌 Короткий пріоритет (що брати першим)\n\n1. **The Singularity (Trinket)** — найцінніший слот із четвірки. Хороший тринкет на старті дає найбільший приріст DPS/HPS.\n2. **The Hara''ti (Belt)** — weekly-gated (прив''язаний до тижневого кд), краще не пропускати тиждень.\n3. **Silvermoon Court (Helm)** — теж зав’язаний на weekly-активність.\n4. **Amani Tribe (Necklace)** — чудовий стат-стік, гнучкий у виборі характеристик.\n\n---\n\n## 1) The Singularity — Тринкет\n\n### Що потрібно:\n* **Умова:** Renown 7 у **The Singularity**\n* **Квест:** <a href=\"https://www.wowhead.com/quest=93933\" data-wowhead=\"quest=93933\">Guarded Treasures</a>\n* **Активність:** Івент **Stormarion Assault** у локації **Voidstorm**\n* **Нагорода:** <a href=\"https://www.wowhead.com/item=264507\" data-wowhead=\"item=264507\">Crucible of Erratic Energies</a>\n\n### 📝 Як отримати:\nПісля досягнення **7-го рівня Renown** у The Singularity вам відкриється квест *Guarded Treasures*. Для його завершення достатньо взяти участь у публічній активності **Stormarion Assault** у Voidstorm. Нагородою стане потужний 246 ilvl Champion тринкет.\n\n> **Чому варто брати рано:** Тринкет — один із найсильніших слотів на старті будь-якого сезону. Він дасть куди більше користі, ніж звичайний шматок броні.\n\n---\n\n## 2) The Hara''ti — Пояс\n\n### Що потрібно:\n* **Умова:** Renown 8 у **The Hara''ti**\n* **Квест:** <a href=\"https://www.wowhead.com/quest=93932\" data-wowhead=\"quest=93932\">Legendary Prosperity</a>\n* **Активність:** Ворлд-івент **Legends of the Haranir** у **Harandar**\n* **Нагорода:** Пояс (246 Champion 1/6)\n\n### 🛡️ Предмети за типом броні:\n* **Cloth:** <a href=\"https://www.wowhead.com/item=263265\" data-wowhead=\"item=263265\">Hara''ti Defender''s Sash</a>\n* **Leather:** <a href=\"https://www.wowhead.com/item=263267\" data-wowhead=\"item=263267\">Hara''ti Defender''s Cord</a>\n* **Mail:** <a href=\"https://www.wowhead.com/item=267481\" data-wowhead=\"item=267481\">Hara''ti Defender''s Belt</a>\n* **Plate:** <a href=\"https://www.wowhead.com/item=263269\" data-wowhead=\"item=263269\">Hara''ti Defender''s Greatbelt</a>\n\n### 📝 Як отримати:\nБеремо **Renown 8** у фракції The Hara''ti, після чого з''являється квест *Legendary Prosperity*. Відправляємось на івент **Legends of the Haranir**, знаходимо необхідний релікт і забираємо свій пояс.\n\n> **Важливо:** Цей предмет підпорядкований **weekly-логіці** (оновлюється щотижня). Спершу добийте Renown 8, а вже потім ідіть робити тижневу активність, щоб випадково не втратити нагороду цього тижня.\n\n---\n\n## 3) Silvermoon Court — Шолом\n\n### Що потрібно:\n* **Умова:** Renown 9 у **Silvermoon Court**\n* **Квест:** <a href=\"https://www.wowhead.com/quest=93930\" data-wowhead=\"quest=93930\">Courting Success</a>\n* **Активність:** **Saltheril''s Soiree** у **Eversong Woods**\n* **Додаткова умова:** Запросити одну з noble-фракцій і виконати її **Runestone weekly quest**\n* **Нагорода:** Шолом (246 Champion 1/6)\n\n### 🛡️ Предмети за типом броні:\n* **Cloth:** <a href=\"https://www.wowhead.com/item=266429\" data-wowhead=\"item=266429\">Silvermoon Sunspire</a>\n* **Leather:** <a href=\"https://www.wowhead.com/item=266430\" data-wowhead=\"item=266430\">Silvermoon Sunguard</a>\n* **Mail:** <a href=\"https://www.wowhead.com/item=266431\" data-wowhead=\"item=266431\">Silvermoon Sunveil</a>\n* **Plate:** <a href=\"https://www.wowhead.com/item=266432\" data-wowhead=\"item=266432\">Silvermoon Suncrest</a>\n\n### 📝 Як отримати:\nНа **9-му рівні Renown** з Silvermoon Court беремо квест *Courting Success*. Йдемо в **Saltheril''s Soiree**, запрошуємо потрібну фракцію аристократів і виконуємо їхній тижневий квест.\n\n> **Важливо:** Як і з поясом, це **weekly-gated** предмет. Правило те саме: спочатку Renown, потім — тижнева активність!\n\n---\n\n## 4) Amani Tribe — Намисто (Necklace)\n\n### Що потрібно:\n* **Умова:** Renown 9 у **Amani Tribe**\n* **Квест:** <a href=\"https://www.wowhead.com/quest=93931\" data-wowhead=\"quest=93931\">An Abundance of Wealth</a>\n* **Активність:** Івент у печері **Abundance**\n* **Нагорода:** Намисто (246 Champion 1/6)\n\n### 📿 Варіанти намиста:\n* **Haste / Crit:** <a href=\"https://www.wowhead.com/item=265739\" data-wowhead=\"item=265739\">Amani Heartstring Pendant</a>\n* **Mastery / Vers:** <a href=\"https://www.wowhead.com/item=265740\" data-wowhead=\"item=265740\">Amani Totemstring</a>\n\n### 📝 Як отримати:\nАпнувши **Renown 9** у Amani Tribe, ви отримаєте квест *An Abundance of Wealth*. Виконуємо івент у відповідній печері та забираємо намисто.\n\n> **Чому цей предмет зручний:** У вас є вибір між двома варіантами характеристик. Ви можете підібрати саме те намисто, яке ідеально підходить під стат-пріоритет вашого спеку!","author":"Sebas","date":"2026-03-13","last_modified_at":"2026-03-13","categories":"WoW Midnight, Гайд","tags":"Midnight, Renown, 246 ilvl, The Singularity, The Hara''ti, Silvermoon Court, Amani Tribe","image":"/assets/img/news-placeholder.webp","revision":1,"updated_at":"2026-10-15T00:00:00.000Z"}'::jsonb) ON CONFLICT (collection,doc_id) DO NOTHING;
INSERT INTO documents(collection,doc_id,data) VALUES ('siteArticles','guides:the-voidspire-raid-guide','{"kind":"guides","slug":"the-voidspire-raid-guide","title":"The Voidspire — короткий гайд по рейду","description":"Короткий і структурований гайд по рейду The Voidspire у World of Warcraft: Midnight.","body":"**The Voidspire** — головний рейд першого сезону доповнення **World of Warcraft: Midnight**, реліз якого відбувся у **березні 2026 року**.  \nРейд розташований у центрі нової зони **Voidstorm (Буря Бездни)**.\n\n---\n\n## Вхід у рейд\n\nВхід до **The Voidspire** розташований у зоні **Voidstorm** в **Quel''Thalas**.\n\n- рейд видно здалеку — це масивний темний шпиль, що височіє над зоною\n- вхід знаходиться на зовнішній платформі біля основи шпиля\n- дістатися можна через зону **Voidstorm**, рухаючись до центральної структури\n- можливий портал із великих столиць фракцій\n\n> **Порада:** бажано поставити **Hearthstone** у найближчій таверні зон Midnight.\n\n---\n\n## Рекомендована корисність для рейду\n\nThe Voidspire побудований навколо:\n\n- **interrupt**\n- **dispel**\n- **soak-механік**\n- чітко розподілених ролей\n\n### Мінімально бажано\n\n- щонайменше **2 гравці для стабільних interrupt** на 3 босі\n- достатньо **raid cooldowns** для фінальної фази останнього бою\n- окрема група для **orb interception** на Heroic/Mythic\n- танки з готовим **active mitigation** у критичні моменти\n\n---\n\n## Список босів\n\n| № | Бос | Ключова особливість |\n|---|---|---|\n| 1 | **<a href=\"https://www.wowhead.com/npc=240435\" data-wowhead=\"npc=240435\">Imperator Averzian</a>** | Бій на сітці **3x3**; не можна дати босу захопити **три клітинки в ряд** |\n| 2 | **<a href=\"https://www.wowhead.com/npc=240434\" data-wowhead=\"npc=240434\">Vorasius</a>** | Гігантський монстр; потрібно **знищувати кришталеві стіни**, щоб вижити під час променю |\n| 3 | **<a href=\"https://www.wowhead.com/npc=240432\" data-wowhead=\"npc=240432\">Fallen-King Salhadaar</a>** | **DPS-check**; необхідно знищувати **сфери Бездни**, перш ніж вони досягнуть боса |\n| 4 | **<a href=\"https://www.wowhead.com/npc=250892\" data-wowhead=\"npc=242056\">Vaelgor</a> & <a href=\"https://www.wowhead.com/npc=250892\" data-wowhead=\"npc=244552\">Ezzorak</a>** | Подвійний бій із драконами; їхнє здоров’я має бути **приблизно на одному рівні** |\n| 5 | **<a href=\"https://www.wowhead.com/npc=250589\" data-wowhead=\"npc=250589\">Lightblinded Vanguard</a>** | Рада з трьох босів-паладинів; кожен має **унікальну ауру**, що впливає на весь рейд |\n| 6 | **<a href=\"https://www.wowhead.com/npc=244761\" data-wowhead=\"npc=244761\">Crown of the Cosmos / Alleria Windrunner</a>** | Фінальний бій рейду з багатофазною структурою та найвищою щільністю механік |\n\n---\n\n## Детально по босах\n\n## 1. Imperator Averzian\n\n> Бій побудований навколо **контролю поля 3x3**.  \n> Завдання рейду — **не дати босу отримати три клітинки в ряд**.\n\n### Основні здібності\n\n| Ability | Що робить | Хто страждає | Що робити |\n|---|---|---|---|\n| **<a href=\"https://www.wowhead.com/spell=1251361\" data-wowhead=\"spell=1251361\">Shadow''s Advance</a>** | Викликає **Abyssal Voidshapers**, відкидає гравців і **назавжди захоплює територію** | DPS | Швидко вбивати аддів. Якщо не вбити — територія втрачена назавжди |\n| **<a href=\"https://www.wowhead.com/spell=1251583\" data-wowhead=\"spell=1251583\">March of the Endless</a>** | Три суміжні портали підсилюють один одного і запускають нескінченну хвилю void damage | Усі | Не дозволяти босу зібрати **три клітинки в ряд** |\n| **<a href=\"https://www.wowhead.com/spell=1249262\" data-wowhead=\"spell=1249262\">Umbral Collapse</a>** | Великий Shadow damage, який зменшується кількістю гравців у soak; також запобігає захопленню клітинки | Танки + soak-групи | Заздалегідь призначити **2 soak-групи** і заходити в зону удару |\n| **<a href=\"https://www.wowhead.com/spell=1249251\" data-wowhead=\"spell=1249251\">Dark Upheaval</a>** | Raid-wide Shadow pulse + постійний фоновий урон | Усі | Хілерам заздалегідь планувати cooldowns |\n| **<a href=\"https://www.wowhead.com/spell=1253918\" data-wowhead=\"spell=1253918\">Imperator''s Glory</a>** | 99% damage reduction і більше шкоди, якщо бос біля захоплених клітинок | Танки | Тримати боса **подалі від зайнятої території** |\n| **<a href=\"https://www.wowhead.com/spell=1265540\" data-wowhead=\"spell=1265540\">Blackening Wounds</a>** | Танковий дебаф, що зменшує максимальне HP за кожен melee hit | Танки | Вчасний **tank swap** |\n| **<a href=\"https://www.wowhead.com/spell=1255749\" data-wowhead=\"spell=1255749\">Gathering Darkness</a>** | Voidshaper перетворюється на сильнішу форму, якщо каст проходить | DPS | **Interrupt + focus kill** |\n| **<a href=\"https://www.wowhead.com/spell=1255702\" data-wowhead=\"spell=1255702\">Pitch Bulwark</a>** | Shadowguard Stalwart дає великий absorb союзникам поряд | DPS | Обов’язково **interrupt** |\n\n### Коротка стратегія\n\n- перед пулом призначити **2 soak-групи**\n- під час циклу з’являються **3 адди** у різних клітинках + **2 soaks**\n- забираються лише **2 позиції**\n- третя позиція віддається босу, тому треба планувати карту наперед\n- пріоритет цілей: **Abyssal Voidshapers**\n- танк веде боса в бік **вільних клітинок**\n\n---\n\n## 2. Vorasius\n\n> Центральна ідея бою — **кришталеві стіни** та **керування паразитами**.  \n> Якщо перед **Void Breath** лишиться хоча б одна стіна, частина рейду просто не матиме куди тікати.\n\n### Основні здібності\n\n| Ability | Що робить | Хто страждає | Що робити |\n|---|---|---|---|\n| **<a href=\"https://www.wowhead.com/spell=1281954\" data-wowhead=\"spell=1281954\">Shadowclaw Slam</a>** | Потужний удар у зону, або raid-wide damage, якщо ніхто не стоїть у місці удару; також запускає появу стін | Танки | Танки мають завжди приймати slam у потрібній точці |\n| **<a href=\"https://www.wowhead.com/spell=1244097\" data-wowhead=\"spell=1244097\">Crystaline Eruption</a>** | Після frenzy формуються **кришталеві стіни** | Усі | Танки мають розкладати стіни **передбачувано** |\n| **<a href=\"https://www.wowhead.com/spell=1254199\" data-wowhead=\"spell=1254199\">Parasite Expulsion</a>** | З’являються **Blistercreep**-адди, що рухаються до гравців | DPS | Кайтери ведуть їх у стіни |\n| **<a href=\"https://www.wowhead.com/spell=1259184\" data-wowhead=\"spell=1259184\">Blisterburst</a>** | Вибух від смерті Blistercreep, що руйнує crystal wall | Координація | Вбивати аддів **біля стіни**, щоб підірвати її |\n| **<a href=\"https://www.wowhead.com/spell=1260046\" data-wowhead=\"spell=1260046\">Primordial Roar</a>** | Притягує всіх до себе, потім відкидає і дає stacking Shadow pressure | Усі | Стояти не занадто щільно; хілерам готувати cooldowns |\n| **<a href=\"https://www.wowhead.com/spell=1244419\" data-wowhead=\"spell=1244419\">Overpowering Pulse</a>** | Shadow damage по рейду, якщо ніхто не в melee range | Melee / рейд | Підтримувати **melee uptime** |\n| **<a href=\"https://www.wowhead.com/spell=1243853\" data-wowhead=\"spell=1243853\">Void Breath</a>** | Смертельний sweeping beam по арені | Усі | **Обидві стіни мають бути зруйновані** до касту |\n\n### Цикл бою\n\n1. Танки приймають **slams**\n2. Формуються **кришталеві стіни**\n3. З’являються **parasites**\n4. Аддів ведуть у стіни\n5. Стіни вибухають\n6. Рейд уникає **Void Breath**\n7. Повтор циклу\n\n### Критична умова вайпу\n\n> **Жива стіна під час Void Breath = майже гарантований вайп.**\n\n---\n\n## 3. Fallen-King Salhadaar\n\n> Це перший справжній **complexity check** рейду.  \n> Бій зав’язаний на **energy bar**, **орбах**, **add control**, **dispels** і правильному русі по кімнаті.\n\n### Основні здібності\n\n| Ability | Що робить | Role Priority | Що робити |\n|---|---|---|---|\n| **<a href=\"https://www.wowhead.com/spell=1246175\" data-wowhead=\"spell=1246175\">Entropic Unraveling</a>** | Пасивно накопичує енергію; на 100 енергії — сильний raid damage, але бос отримує +25% damage taken | Усі | Тримати cooldowns на burn window і уникати Umbral Beams |\n| **<a href=\"https://www.wowhead.com/spell=1247738\" data-wowhead=\"spell=1247738\">Void Convergence</a>** | Дві сфери летять до боса; якщо доходять — великий raid damage + stacking DoT | DPS | Знищувати **обидві сфери**, але **не одночасно** |\n| **Dark Radiation** | Raid-wide Shadow DoT після знищення кожної сфери | Healers | Орби треба вбивати **із затримкою**, щоб не стакати надмірний тиск |\n| **Fractured Projection** | Спавнить образи Salhadaar, які кастують **Shadow Fracture** | DPS | Контроль і знищення аддів **до орбів** |\n| **<a href=\"https://www.wowhead.com/spell=1248697\" data-wowhead=\"spell=1248697\">Despotic Command</a>** | Дебаф на кількох гравцях; після завершення лишає absorb + постійну небезпечну зону | Marked players | Виходити на край кімнати перед dispel/expiry |\n| **<a href=\"https://www.wowhead.com/spell=1250803\" data-wowhead=\"spell=1250803\">Shattering Twilight</a>** | Темна зоря в активного танка, велика шкода + шипи назовні | Танки | Відвертати боса від рейду перед кастом |\n| **<a href=\"https://www.wowhead.com/spell=1284963\" data-wowhead=\"spell=1284963\">Destabilizing Strikes</a>** | Стакаючий Shadow DoT по активному танку | Танки | Робити **tank swap** до критичних стаків |\n| **Twisting Obscurity** | Ланцюговий Shadow bolt по рейду з DoT | Healers | Підготувати burst healing |\n\n### Ключові принципи бою\n\n- **орби** — пріоритет\n- орби вбиваються **по черзі**\n- **Fractured Images** потрібно контролювати швидко\n- гравці з **Despotic Command** виходять на край\n- танки не розвертають небезпечні механіки в рейд\n- burn window настає під **Entropic Unraveling**\n\n---\n\n## 4. Vaelgor & Ezzorak\n\n> Подвійний бій, де головна умова — **не допустити різниці HP більше ніж 10%**.\n\n### Основні механіки\n\n| Mechanic | Description | Що робити |\n|---|---|---|\n| **Twilight Bond** | Якщо різниця між HP босів перевищує 10%, сильніший починає наносити набагато більше шкоди | Призначити окремого **caller**, який стежить за HP і командує свіч |\n| **<a href=\"https://www.wowhead.com/spell=1249748\" data-wowhead=\"spell=1249748\">Midnight Flames</a>** | Обидва дракони кастують небезпечну комбінацію вогню і void; треба сховатись у бар’єрі | Заздалегідь знайти **Lightbound Vanguard barrier** і зайти в неї |\n| **<a href=\"https://www.wowhead.com/spell=1245391\" data-wowhead=\"spell=1245391\">Gloom Orbs</a>** | Сфери перетинають арену, їх треба soak-ати командами | Призначити **soak-групи** та чергувати їх |\n| **Aerial Phase** | Один із драконів піднімається в повітря і бомбардує арену | Стежити, який бос у повітрі, і не втрачати контроль над наземними механіками |\n| **Simultaneous Kill** | Обидва боси мають померти майже одночасно | На ~5% HP зупинити шкоду в нижчого і вирівняти обох |\n\n### Коротка стратегія\n\n- постійний контроль **HP обох босів**\n- обережний cleave\n- швидке перемикання DPS\n- бар’єр під **Midnight Flames**\n- чергування soak-груп\n- одночасне добивання в фіналі\n\n---\n\n## 5. Lightblinded Vanguard\n\n> Рада з трьох босів-паладинів, де кожен має власну ауру, що змінює темп бою для всього рейду.\n\n### Основні здібності\n\n| Ability | Що робить | Що робити |\n|---|---|---|\n| **Aura of Wrath** | Посилює тиск по рейду та підштовхує до агресивнішого хілу | Планувати defensives і raid cooldowns |\n| **Aura of Devotion** | Підсилює захист босів і затягує бій | Чітко тримати DPS-пріоритет |\n| **Aura of Peace** | Змінює темп бою й змушує уважніше грати від позиціонування | Не метушитися й тримати порядок у русі |\n| **<a href=\"https://www.wowhead.com/spell=1248652\" data-wowhead=\"spell=1248652\">Divine Toll</a>** | Потужний burst-ефект по рейду/цілях | Готувати burst healing або defensives |\n| **<a href=\"https://www.wowhead.com/spell=1246487\" data-wowhead=\"spell=1246487\">Avenger''s Shield</a>** | Небезпечний bounce / pressure-каст | Контролювати позиціонування і переривання де можливо |\n| **<a href=\"https://www.wowhead.com/spell=1251859\" data-wowhead=\"spell=1251859\">Shield of the Righteous</a>** | Високий фронтальний / танковий тиск | Танкам уважно відвертати й переживати удари |\n| **<a href=\"https://www.wowhead.com/spell=1258514\" data-wowhead=\"spell=1258514\">Blinding Light</a>** | Тиск по рейду / контроль простору | Вчасно розходитися і переживати burst |\n| **<a href=\"https://www.wowhead.com/spell=1248674\" data-wowhead=\"spell=1248674\">Sacred Shield</a>** | Великий absorb / захисний ефект | Вчасно перемикати пріоритет DPS |\n| **<a href=\"https://www.wowhead.com/spell=1248718\" data-wowhead=\"spell=1248718\">Tyr''s Wrath</a>** | Сильний рейдовий тиск | Підготувати healing cooldowns |\n| **<a href=\"https://www.wowhead.com/spell=1255739\" data-wowhead=\"spell=1255739\">Searing Radiance</a>** | Holy/Fire pressure по рейду | Хілерам тримати рейд стабільним |\n| **<a href=\"https://www.wowhead.com/spell=1246745\" data-wowhead=\"spell=1246745\">Exorcism</a>** | Точковий небезпечний каст | Пріоритетно контролювати ціль і відхілювати урон |\n\n### Коротка логіка бою\n\n- слідкувати за тим, **яка аура активна**\n- підлаштовувати рейд під поточний ефект\n- правильно розподіляти цілі й defensive cooldowns\n- уникати хаотичного руху під час накладення аур\n\n---\n\n## 6. Crown of the Cosmos / Alleria Windrunner\n\n> Фінал рейду — багатофазний бій із високою щільністю механік.  \n> У тексті детальний опис поданий через **Alleria Windrunner** як фінальну сутичку на вершині шпиля.\n\n### Основні механіки\n\n| Mechanic | Description | Execution |\n|---|---|---|\n| **Undying Sentinels (Phase 1)** | Одразу з’являються 3 адди; якщо втратити контроль — вайп | Танки мають **миттєво забрати всіх трьох** |\n| **<a href=\"https://www.wowhead.com/spell=1235553\" data-wowhead=\"spell=1235553\">Silverstrike Arrow</a>** | Сильний прицільний постріл, який треба правильно розіграти позиційно | Призначити окремого гравця для контролю позиції |\n| **Gravity Collapse** | У фінальній фазі затягує гравців у collapse points, поки на арені з’являються інші загрози | Завчасне позиціонування + movement abilities |\n| **Final Burn Phase** | Найважча фаза з накладенням кількох механік одночасно | Зберігати всі великі cooldowns і, за потреби, **Lust/Bloodlust** на цю фазу |\n\n### Mythic-відмінність\n\n| Режим | Особливість |\n|---|---|\n| **Mythic** | У фінальній фазі з’являється жорстка послідовність interrupt-ів, де одна помилка може призвести до вайпу |\n\n### Коротка стратегія\n\n- фаза 1: миттєвий контроль **Undying Sentinels**\n- чітке позиціонування під **Silverstrike Arrow**\n- у фіналі: одночасний контроль **Gravity Collapse** та інших аномалій\n- усі важливі **raid cooldowns** зберігати на заключний burn\n\n---\n\n## Рекомендований ilvl\n\n| Режим | Рекомендація |\n|---|---|\n| **LFR** | приблизно **220 ilvl** |\n| **Normal / Heroic** | формальної вимоги немає, потрібна підготовлена група |\n| **Mythic** | практичний поріг близько **245+ ilvl** |\n\n---\n\n## Підсумок\n\n**The Voidspire** — це рейд, побудований навколо:\n\n- **контролю простору**\n- **правильного позиціонування**\n- **розподілу soak / interrupts / dispels**\n- **чіткої координації між ролями**\n\nКожен бос вводить окрему систему:\n\n- **Imperator Averzian** — контроль території\n- **Vorasius** — руйнування стін\n- **Fallen-King Salhadaar** — орби, енергія та add control\n- **Vaelgor & Ezzorak** — баланс HP\n- **Lightblinded Vanguard** — контроль аур\n- **Crown of the Cosmos / Alleria** — багатофазний фінал із найвищим навантаженням на рейд","author":"Sebas","date":"2026-03-13","last_modified_at":"2026-03-13","categories":"WoW Midnight, Рейд","tags":"The Voidspire, Midnight, Voidstorm, Raid","image":"/assets/img-content/the-voidspire-raid.webp","revision":1,"updated_at":"2026-10-15T00:00:00.000Z"}'::jsonb) ON CONFLICT (collection,doc_id) DO NOTHING;
INSERT INTO documents(collection,doc_id,data) VALUES ('siteArticles','guides:the-dreamrift-raid-guide','{"kind":"guides","slug":"the-dreamrift-raid-guide","title":"The Dreamrift — короткий гайд по рейду","description":"Короткий і структурований гайд по рейду The Dreamrift у World of Warcraft: Midnight.","body":"**The Dreamrift** — однобосовий рейд першого сезону **World of Warcraft: Midnight**.  \nРейд розташований у **Harandar**, глибоко в **Rift of Aln**, а єдиний бос тут — <a href=\"https://www.wowhead.com/npc=256116/chimaerus\" data-wowhead=\"npc=256116\">Chimaerus, the Undreamt God</a>.\n\nНа відміну від великих рейдів, тут немає довгого маршруту й пачок трешу: ви заходите всередину й майже одразу починаєте бій. Швидко, зручно і дуже боляче, якщо рейд незібраний.\n\n---\n\n## Коротко про рейд\n\n| Параметр | Значення |\n|---|---|\n| **Локація** | Harandar, Rift of Aln |\n| **Вхід** | `/way 61.0 64.2` |\n| **Боси** | 1 — <a href=\"https://www.wowhead.com/npc=256116/chimaerus\" data-wowhead=\"npc=256116\">Chimaerus, the Undreamt God</a> |\n| **Мінімальний ilvl для LFR** | 220 |\n| **Головна нагорода** | chest tier token |\n| **Треш** | немає |\n\n---\n\n## Вхід у рейд\n\nВхід до **The Dreamrift** розташований у **південно-східній частині Harandar**, у зоні **Rift of Aln**.\n\n- координати входу: **/way 61.0 64.2**\n- шукати потрібно **на нижньому рівні** локації\n- якщо здається, що входу не видно, просто спустіться нижче\n\n> **Порада:** тут немає трешу, тому підготовка до бою починається майже одразу після входу.\n\n---\n\n## Який склад рейду тут особливо корисний\n\nЦе **один довгий бій**, у якому головне — контроль аддів, збивання кастів і швидке перемикання між цілями. Тому рейду дуже допоможуть:\n\n- надійні **interrupt-и**\n- достатній **burst AoE**\n- гравці, які швидко перемикаються на пріоритетні цілі\n- сильні **рейдові захисні та healing cooldowns** на другу фазу\n\n### Що особливо важливо\n\n- **Haunting Essence** кастують небезпечні заклинання, які потрібно збивати\n- частина механік зав’язана на <a href=\"https://www.wowhead.com/spell=1245698/alnsight\" data-wowhead=\"spell=1245698\">Alnsight</a> і поділ рейду між двома вимірами\n- слабкий контроль аддів тут карається дуже швидко\n\n---\n\n## Бос: <a href=\"https://www.wowhead.com/npc=256116/chimaerus\" data-wowhead=\"npc=256116\">Chimaerus, the Undreamt God</a>\n\nУвесь бій проти <a href=\"https://www.wowhead.com/npc=256116/chimaerus\" data-wowhead=\"npc=256116\">Chimaerus</a> побудований навколо однієї ідеї:\n\n> **не дати босу поглинути Manifestations**\n\nЯкщо адди доживають до небезпечних моментів, бос отримує <a href=\"https://www.wowhead.com/spell=1245844/cannibalized-essence\" data-wowhead=\"spell=1245844\">Cannibalized Essence</a>, лікується й починає бити дедалі сильніше. Якщо таких стеків назбирається багато, бій практично програний.\n\n---\n\n## Головна причина вайпу\n\n### <a href=\"https://www.wowhead.com/spell=1245844/cannibalized-essence\" data-wowhead=\"spell=1245844\">Cannibalized Essence</a>\n\nКожен **Manifestation**, якого <a href=\"https://www.wowhead.com/npc=256116/chimaerus\" data-wowhead=\"npc=256116\">Chimaerus</a> встигає поглинути:\n\n- **лікує боса**\n- **збільшує його шкоду на 50%**\n- ефект **накопичується**\n\n> **Суть бою:** що довше живуть адди, то ближче рейд до вайпу.\n\n---\n\n# Фаза 1 — Insatiable Hunger\n\nПерша фаза — це основний цикл бою. У ній рейд працює одразу з двома шарами реальності:\n\n- **Reality**\n- **Rift / Aln**\n\nПісля <a href=\"https://www.wowhead.com/spell=1262289/alndust-upheaval\" data-wowhead=\"spell=1262289\">Alndust Upheaval</a> частина гравців отримує <a href=\"https://www.wowhead.com/spell=1245698/alnsight\" data-wowhead=\"spell=1245698\">Alnsight</a> і потрапляє у вимір Rift.  \nСаме ці гравці можуть бачити й бити **Manifestations** до того, як ті повністю вийдуть у звичайну реальність.\n\n## Як працює фаза 1\n\n- гравці з <a href=\"https://www.wowhead.com/spell=1245698/alnsight\" data-wowhead=\"spell=1245698\">Alnsight</a> вбивають Manifestations у Rift\n- якщо не встигнути, адди переходять у **Reality**\n- після цього вони рухаються до боса\n- якщо бос їх поглинає, рейд отримує стек <a href=\"https://www.wowhead.com/spell=1245844/cannibalized-essence\" data-wowhead=\"spell=1245844\">Cannibalized Essence</a>\n\n---\n\n## Основні здібності фази 1\n\n| Здібність | Небезпека | Що робити |\n|---|---|---|\n| <a href=\"https://www.wowhead.com/spell=1262289/alndust-upheaval\" data-wowhead=\"spell=1262289\">Alndust Upheaval</a> | Висока | Визначає, хто отримає <a href=\"https://www.wowhead.com/spell=1245698/alnsight\" data-wowhead=\"spell=1245698\">Alnsight</a>. Заздалегідь розпишіть ротацію |\n| <a href=\"https://www.wowhead.com/spell=1258610/rift-emergence\" data-wowhead=\"spell=1258610\">Rift Emergence</a> | Висока | Починає нову хвилю проблем: з’являються адди, а рейд отримує додатковий тиск |\n| **Titan Fragment Meld** | Дуже висока | Щит на Manifestations у Rift. Його мають швидко зламати гравці з <a href=\"https://www.wowhead.com/spell=1245698/alnsight\" data-wowhead=\"spell=1245698\">Alnsight</a> |\n| <a href=\"https://www.wowhead.com/spell=1252863/insatiable\" data-wowhead=\"spell=1252863\">Insatiable</a> | Смертельна | Пасивна механіка, через яку бос автоматично поглинає аддів у радіусі досяжності |\n| <a href=\"https://www.wowhead.com/spell=1245396/consume\" data-wowhead=\"spell=1245396\">Consume</a> | Смертельна | Наприкінці каналу бос поглинає всіх живих Manifestations поруч |\n| **Discordant Roar** | Висока | Великий адд завдає дедалі сильнішої шкоди всьому рейду |\n| <a href=\"https://www.wowhead.com/spell=1249017/fearsome-cry\" data-wowhead=\"spell=1249017\">Fearsome Cry</a> | Середня / висока | Каст потрібно обов’язково збивати |\n| <a href=\"https://www.wowhead.com/spell=1257087/consuming-miasma\" data-wowhead=\"spell=1257087\">Consuming Miasma</a> *(Heroic+)* | Висока | Диспельте тільки подалі від рейду |\n| <a href=\"https://www.wowhead.com/spell=1246621/caustic-phlegm\" data-wowhead=\"spell=1246621\">Caustic Phlegm</a> | Середня | Постійна шкода по рейду, яку потрібно стабільно відхілювати |\n| <a href=\"https://www.wowhead.com/spell=1272726/rending-tear\" data-wowhead=\"spell=1272726\">Rending Tear</a> | Середня | Танкова фронталка — боса потрібно тримати відвернутим від рейду |\n| **Rift Madness** *(Mythic)* | Дуже висока | Гравці в Rift можуть шкодити союзникам і втрачати контроль |\n| **Dissonance** *(Mythic)* | Висока | Карає за неправильне позиціонування між вимірами |\n\n---\n\n## Що робити DPS\n\n### 1. Дотримуватися ротації <a href=\"https://www.wowhead.com/spell=1245698/alnsight\" data-wowhead=\"spell=1245698\">Alnsight</a>\nНе можна відправляти всіх у Rift одночасно.  \nПотрібна чітка ротація, щоб у кожній хвилі були люди, які можуть убивати Manifestations.\n\n### 2. Убивати Manifestations до переходу в Reality\nЩо довше живе адд, то вищий шанс, що він:\n- вийде в реальність\n- дійде до боса\n- стане їжею для <a href=\"https://www.wowhead.com/npc=256116/chimaerus\" data-wowhead=\"npc=256116\">Chimaerus</a>\n\n### 3. Збивати касти Haunting Essence\nНайнебезпечніші з них:\n- <a href=\"https://www.wowhead.com/spell=1249017/fearsome-cry\" data-wowhead=\"spell=1249017\">Fearsome Cry</a>\n- <a href=\"https://www.wowhead.com/spell=1261997/essence-bolt\" data-wowhead=\"spell=1261997\">Essence Bolt</a>\n\n### 4. Не стояти в <a href=\"https://www.wowhead.com/spell=1263026/alndust-essence\" data-wowhead=\"spell=1263026\">Alndust Essence</a>\nПісля смерті аддів лишаються калюжі, які:\n- завдають шкоди\n- сповільнюють рух\n\n### 5. Швидко перемикатися на Colossal Horror\nЦей великий адд небезпечний через **Discordant Roar**, який дедалі сильніше тисне на весь рейд.\n\n---\n\n## Що робити хілерам\n\n### 1. Стежити за тиском від <a href=\"https://www.wowhead.com/spell=1250953/rift-sickness\" data-wowhead=\"spell=1250953\">Rift Sickness</a>\nКожен повноцінний вихід адда в Reality посилює навантаження на рейд.\n\n### 2. Обережно працювати з <a href=\"https://www.wowhead.com/spell=1257087/consuming-miasma\" data-wowhead=\"spell=1257087\">Consuming Miasma</a>\nНа Heroic і вище:\n- це довгий DoT\n- диспел створює вибух\n- диспелити потрібно **поза групою**\n\n### 3. Берегти основні cooldowns на Phase 2\nНе витрачайте все у першій фазі без нагальної потреби — у повітряній фазі буде набагато важче.\n\n---\n\n## Що робити танкам\n\n### 1. Одразу забирати Colossal Horror\nЯкщо великий адд лишається без танка, він дуже швидко влаштовує хаос.\n\n### 2. Контролювати позицію боса перед <a href=\"https://www.wowhead.com/spell=1245396/consume\" data-wowhead=\"spell=1245396\">Consume</a>\nВід позиції боса прямо залежить, скільки аддів опиниться в радіусі поглинання.\n\n### 3. Не повертати фронталку в рейд\n<a href=\"https://www.wowhead.com/spell=1272726/rending-tear\" data-wowhead=\"spell=1272726\">Rending Tear</a> не можна спрямовувати в групу.\n\n### 4. На Heroic+ стежити за <a href=\"https://www.wowhead.com/spell=1253744/rift-vulnerability\" data-wowhead=\"spell=1253744\">Rift Vulnerability</a>\nНадто довге перебування в Rift робить наступні механіки значно небезпечнішими.\n\n---\n\n## Коротка стратегія фази 1\n\n1. Розподіліть гравців у ротацію на <a href=\"https://www.wowhead.com/spell=1245698/alnsight\" data-wowhead=\"spell=1245698\">Alnsight</a>\n2. Ламайте **Titan Fragment Meld**\n3. Убивайте Manifestations до їхнього виходу в Reality\n4. Збивайте <a href=\"https://www.wowhead.com/spell=1249017/fearsome-cry\" data-wowhead=\"spell=1249017\">Fearsome Cry</a> і <a href=\"https://www.wowhead.com/spell=1261997/essence-bolt\" data-wowhead=\"spell=1261997\">Essence Bolt</a>\n5. Швидко забирайте **Colossal Horror**\n6. Не допускайте великої кількості живих аддів перед <a href=\"https://www.wowhead.com/spell=1245396/consume\" data-wowhead=\"spell=1245396\">Consume</a>\n\n---\n\n# Фаза 2 — To The Skies\n\nКоли <a href=\"https://www.wowhead.com/npc=256116/chimaerus\" data-wowhead=\"npc=256116\">Chimaerus</a> набирає **100 енергії**, він злітає в повітря.\n\nУ цій фазі:\n- бос починає постійно тиснути по рейду зверху\n- адди продовжують з’являтися\n- наприкінці фази бос різко повертається вниз і **миттєво поглинає всіх живих Manifestations**\n\nЦе найнебезпечніший момент бою.\n\n---\n\n## Основні здібності фази 2\n\n| Здібність | Небезпека | Що робити |\n|---|---|---|\n| <a href=\"https://www.wowhead.com/spell=1245486/corrupted-devastation\" data-wowhead=\"spell=1245486\">Corrupted Devastation</a> | Дуже висока | Тут потрібні головні healing і defensive cooldowns |\n| <a href=\"https://www.wowhead.com/spell=1245406/ravenous-dive\" data-wowhead=\"spell=1245406\">Ravenous Dive</a> | Смертельна | До цього моменту арену треба максимально зачистити від живих аддів |\n| <a href=\"https://www.wowhead.com/spell=1262289/alndust-upheaval\" data-wowhead=\"spell=1262289\">Alndust Upheaval</a> *(Mythic, перед злетом)* | Висока | Додає ще більше хаосу перед повітряною фазою |\n\n---\n\n## Головна ідея другої фази\n\n> **Усі живі адди перед <a href=\"https://www.wowhead.com/spell=1245406/ravenous-dive\" data-wowhead=\"spell=1245406\">Ravenous Dive</a> = безкоштовні стаки <a href=\"https://www.wowhead.com/spell=1245844/cannibalized-essence\" data-wowhead=\"spell=1245844\">Cannibalized Essence</a> для боса**\n\nТобто друга фаза — це не просто перевірка на виживання. Потрібно одночасно:\n\n- пережити сильну шкоду по рейду\n- не втратити контроль над Manifestations\n- увійти в приземлення боса з максимально чистою ареною\n\n---\n\n## Коротка стратегія фази 2\n\n- зберігайте головні **рейдові cooldowns** саме на цю фазу\n- не припиняйте контроль аддів лише тому, що бос у повітрі\n- не заходьте в приземлення з живими Manifestations\n- до <a href=\"https://www.wowhead.com/spell=1245406/ravenous-dive\" data-wowhead=\"spell=1245406\">Ravenous Dive</a> арена має бути максимально зачищена\n\n---\n\n## Загальні поради\n\n- це **однобосовий рейд**, але він зовсім не “безкоштовний”\n- головна перевірка тут — **координація**\n- найчастіші причини вайпу:\n  - слабка ротація <a href=\"https://www.wowhead.com/spell=1245698/alnsight\" data-wowhead=\"spell=1245698\">Alnsight</a>\n  - пропущені interrupt-и\n  - занадто багато живих аддів перед <a href=\"https://www.wowhead.com/spell=1245396/consume\" data-wowhead=\"spell=1245396\">Consume</a> або <a href=\"https://www.wowhead.com/spell=1245406/ravenous-dive\" data-wowhead=\"spell=1245406\">Ravenous Dive</a>\n\nРейд має чітко розуміти:\n- хто йде в Rift\n- хто збиває касти\n- хто забирає великих аддів\n- які cooldowns зберігаються на другу фазу\n\n---\n\n## Чому цей рейд важливий\n\n**The Dreamrift** — швидкий, але цінний рейд сезону:\n\n- лише **1 бос**\n- без трешу\n- швидкий weekly clear після освоєння\n- саме тут падає **chest tier token**\n\n---\n\n## Підсумок\n\n**The Dreamrift** короткий за структурою, але дуже вимогливий за виконанням.  \nБій із <a href=\"https://www.wowhead.com/npc=256116/chimaerus\" data-wowhead=\"npc=256116\">Chimaerus</a> карає не за низький DPS сам по собі, а за:\n\n- слабкий контроль аддів\n- погану ротацію <a href=\"https://www.wowhead.com/spell=1245698/alnsight\" data-wowhead=\"spell=1245698\">Alnsight</a>\n- неправильні рішення з dispel та interrupt\n- відсутність плану cooldowns на другу фазу\n\nЯкщо рейд дисципліновано працює з Manifestations і не годує ними боса, енкаунтер стає керованим.  \nЯкщо ні — <a href=\"https://www.wowhead.com/npc=256116/chimaerus\" data-wowhead=\"npc=256116\">Chimaerus</a> дуже швидко покаже, хто тут справжній apex predator.","author":"Sebas","date":"2026-03-15","last_modified_at":"2026-03-16","categories":"WoW Midnight, Рейд","tags":"The Dreamrift, Chimaerus, Midnight, Harandar, Raid","image":"/assets/img-content/the-dreamrift-raid.webp","revision":1,"updated_at":"2026-10-15T00:00:00.000Z"}'::jsonb) ON CONFLICT (collection,doc_id) DO NOTHING;
INSERT INTO documents(collection,doc_id,data) VALUES ('siteArticles','guides:midnight-mythic-plus-season-1-guide','{"kind":"guides","slug":"midnight-mythic-plus-season-1-guide","title":"Midnight Mythic+ Season 1 — короткий гайд","description":"Короткий і зрозумілий гайд по Mythic+ Season 1 у World of Warcraft: Midnight: пул підземель, афікси, нагороди, KSM і практичні поради.","body":"**Mythic+ у Midnight Season 1 відкривається 24 березня 2026 року.**  \nСам сезон стартує **17 березня**, але в перший тиждень доступні лише **Mythic**-підземелля без ключів. Це дає час спокійно вивчити маршрути, босів і проблемні паки ще до старту таймерів.\n\nГоловна ідея сезону проста: пул підземель фіксований на весь сезон, старт для нових гравців став м’якшим завдяки <a href=\"https://www.wowhead.com/affix=165/lindormis-guidance\" data-wowhead=\"affix=165\">Lindormi''s Guidance</a>, а далі система поступово повертає звичний тиск через <a href=\"https://www.wowhead.com/spell=461918/xalataths-bargain-ascendant\" data-wowhead=\"spell=461918\">Xal''atath''s Bargain: Ascendant</a> та ротацію **Tyrannical / Fortified**.\n\n---\n\n## Що важливо знати одразу\n\n- **Mythic+ стартує 24 березня 2026**\n- **пул із 8 підземель не змінюється протягом сезону**\n- на ключах **+2–+5** працює <a href=\"https://www.wowhead.com/affix=165/lindormis-guidance\" data-wowhead=\"affix=165\">Lindormi''s Guidance</a>\n- з **+5** починають діяти афікси **Xal''atath''s Bargain**\n- **Keystone Master** у Midnight Season 1 — це **2000 Mythic+ Rating**, а не “закрити один +15”\n\n---\n\n## Пул підземель Midnight Season 1\n\nУ першому сезоні ротація складається з **4 підземель Midnight** і **4 повернених підземель з попередніх доповнень**.\n\n| Підземелля | Тип | Коротко |\n|---|---|---|\n| **Magister''s Terrace** | Midnight | оновлена версія знайомого інстансу; компактний маршрут і знайомий темп |\n| **Maisara Caverns** | Midnight | підземна структура, колони для line of sight і небезпечне оточення |\n| **Nexus-Point Xenas** | Midnight | void/arcane стиль, багато небезпечних кастів і складні паки |\n| **Windrunner Spire** | Midnight | вертикальний дизайн, рух і позиціонування тут вирішують дуже багато |\n| **Algeth''ar Academy** | Legacy | знайоме підземелля з Dragonflight, добре підходить для відпрацювання маршруту |\n| **Pit of Saron** | Legacy | відносно лінійне підземелля, зручне для стабільних і контрольованих проходів |\n| **Seat of the Triumvirate** | Legacy | складніше за середнє, багато void-механік і неприємних паків |\n| **Skyreach** | Legacy | мобільне підземелля, де всім ролям важливо добре рухатися |\n\n> Окремих міні-гайдів на кожне підземелля тут немає, тому цей матеріал зосереджений саме на сезоні в цілому: як зайти, як прогресувати й за чим полювати.\n\n---\n\n## Як працюють афікси в Season 1\n\n### <a href=\"https://www.wowhead.com/affix=165/lindormis-guidance\" data-wowhead=\"affix=165\">Lindormi''s Guidance</a> (+2–+5)\n\nЦе новий “навчальний” афікс для ранніх ключів. Він робить старт у Mythic+ значно м’якшим і корисним для тих, хто тільки вчить данжі.\n\nЩо він дає:\n\n- частина **не-босових ворогів** позначається **Temporal Sands**\n- такі цілі завдають **на 5% менше шкоди** і мають **на 5% менше здоров’я**\n- саме ці вороги дають **100% Enemy Forces**, тобто гра фактично підказує базовий маршрут\n- смерті гравців **не штрафують таймер**\n\nПростою мовою: на ключах **+2–+5** гра сама допомагає не заплутатися в маршруті й не валить ключ у смітник через кілька смертей. Це чудовий режим для вивчення пулу сезону.\n\n### <a href=\"https://www.wowhead.com/spell=461918/xalataths-bargain-ascendant\" data-wowhead=\"spell=461918\">Xal''atath''s Bargain: Ascendant</a> і інші Bargain-афікси (+5 і вище)\n\nПочинаючи з **+5**, сезон додає ротаційні афікси **Xal''atath''s Bargain**. Їхня ідея — дати групі додаткову механіку поверх самого підземелля.\n\nНаприклад, <a href=\"https://www.wowhead.com/spell=461918/xalataths-bargain-ascendant\" data-wowhead=\"spell=461918\">Xal''atath''s Bargain: Ascendant</a> створює орби, які потрібно вчасно контролювати. Якщо їх ігнорувати, вони підсилюють ворогів; якщо правильно розіграти, група отримує вигоду замість проблем.\n\n### Tyrannical і Fortified\n\nЦі афікси нікуди не зникли:\n\n- **Tyrannical** — сильніші боси, вищий тиск на single target і defensive cooldowns\n- **Fortified** — сильніший треш, вищі вимоги до маршруту, interrupt-ів і контролю паків\n\nУ практиці це означає дуже просту річ:\n\n- на **Tyrannical** тижнях бійки з босами карають більше\n- на **Fortified** тижнях вас частіше вбиватиме саме треш між босами\n\n---\n\n## Нагороди та рівень предметів\n\nУ Midnight Season 1 нагороди з Mythic+ ростуть поступово. Нижче — найважливіші пороги.\n\n| Рівень | Наприкінці проходження | У Great Vault |\n|---|---|---|\n| **Mythic 0** | Champion 1 (**246**) | Champion 4 (**256**) |\n| **+2 / +3** | Champion 2 (**250**) | Hero 1 (**259**) |\n| **+4** | Champion 3 (**253**) | Hero 2 (**263**) |\n| **+5** | Champion 4 (**256**) | Hero 2 (**263**) |\n| **+6 / +7** | Hero 1 (**259**) | Hero 3–4 (**266–269**) |\n| **+8 / +9** | Hero 2 (**263**) | Hero 4 (**269**) |\n| **+10 і вище** | Hero 3 (**266**) | Myth 1 (**272**) |\n\nЦе зручно читати так:\n\n- **+2–+5** — комфортний вхід і стабільне екіпірування\n- **+6–+9** — основне вікно прогресу\n- **+10+** — починається серйозний push за вищими винагородами й телепортами\n\n---\n\n## Great Vault і телепорти\n\n**Great Vault** залишається одним із найкращих джерел екіпірування в сезоні. Навіть якщо ти не пушиш дуже високі ключі, регулярні закриття підземель щотижня дають сильну довгострокову вигоду.\n\nОкремо варто пам’ятати про телепорти:\n\n- за **вчасне проходження конкретного підземелля на +10 або вище** відкривається **персональний телепорт** саме до цього інстансу\n\nЦе не просто зручність, а ще й економія часу для подальших ключів.\n\n---\n\n## Keystone Master у Midnight Season 1\n\nУ Midnight Season 1 **Keystone Master** отримується за **2000 Mythic+ Rating**.\n\nЗа це ти отримуєш:\n\n- досягнення **Midnight Keystone Master: Season One**\n- маунта **Calamitous Carrion**\n\nТобто KSM у цьому сезоні — це **не один випадковий +15**, а стабільний прогрес по всьому пулу підземель.\n\n### Що це означає на практиці\n\nДля KSM тобі не потрібно грати “як на MDI”. Але потрібно:\n\n- закривати ключі **регулярно**\n- не ігнорувати “слабкі” для твоєї групи підземелля\n- тримати більш-менш рівний прогрес по пулу\n- вчитися грати не лише “в дамаг”, а ще й у **interrupt, defensives, маршрут і виживання**\n\n---\n\n## Простий план прогресу\n\n### Етап 1 — перший тиждень сезону\nПоки ключі ще не відкрилися, пробіжи **Mythic 0** підземелля, щоб:\n- побачити босів і треш\n- зрозуміти небезпечні паки\n- вирішити, де вашій групі важко\n\n### Етап 2 — ключі +2–+5\nЦе найкращий момент, щоб:\n- вивчити фіксований сезонний пул\n- користуватися підказками від <a href=\"https://www.wowhead.com/affix=165/lindormis-guidance\" data-wowhead=\"affix=165\">Lindormi''s Guidance</a>\n- не нервувати через таймер після кожної смерті\n- відточити базовий маршрут\n\n### Етап 3 — ключі +6–+9\nНа цьому етапі вже важливо:\n- добре знати, які паки у вас проблемні\n- розуміти, де потрібні групові cooldowns\n- мати узгоджені interrupt-и\n- поступово вирівнювати рейтинг по всіх підземеллях\n\n### Етап 4 — +10 і далі\nТут починається справжній push:\n- таймінг дрібниць починає вирішувати дуже багато\n- помилки по маршруту караються жорсткіше\n- для телепортів і сильнішого Great Vault треба грати стабільно, а не “раз пощастило”\n\n---\n\n## Що насправді відрізняє сильну групу від середньої\n\n### 1. Маршрут\nФіксований пул означає, що хороший маршрут окупається багато разів. Що краще група знає, **які паки брати, що скіпати і де давати cooldowns**, то легше росте ключ.\n\n### 2. Комунікація\nНавіть прості callouts на кшталт:\n- “мій interrupt”\n- “даю defensive”\n- “наступний pull великий”\n- “тримай stun на орб”\n\nроблять групу значно сильнішою.\n\n### 3. Стабільний склад\nОдна й та сама група з середнім gear часто прогресує краще, ніж випадкові сильні гравці без зіграності.\n\n### 4. Чисте виконання\nНа високих ключах проблема часто не в тому, що “не вистачило DPS”, а в тому, що:\n- пропустили каст\n- зайво померли\n- невчасно використали defensive\n- зламали маршрут\n\n---\n\n## Корисна порада для старту сезону\n\nЯкщо не знаєш, з чого почати, роби так:\n\n1. закрий **Mythic 0** у перший тиждень\n2. на старті Mythic+ проходь **усі 8 підземель на низьких ключах**\n3. визнач 2–3 данжі, які вашій групі даються найкраще\n4. саме на них піднімай ключі швидше\n5. паралельно не занедбуй слабші інстанси, щоб не просісти по рейтингу\n\nЦе простіше й надійніше, ніж одразу бігти “в один улюблений ключ” і потім дивуватися, чому рейтинг стоїть.\n\n---\n\n## Підсумок\n\n**Midnight Mythic+ Season 1** виглядає дружнішим на старті, ніж багато попередніх сезонів, але це не означає, що він легкий.  \nBlizzard зробила вхід у систему м’якшим через <a href=\"https://www.wowhead.com/affix=165/lindormis-guidance\" data-wowhead=\"affix=165\">Lindormi''s Guidance</a>, але далі все одно перемагають ті самі речі:\n\n- знання підземель\n- маршрут\n- interrupt-и\n- defensive cooldowns\n- стабільна групова гра\n\nЯкщо коротко: **спочатку вивчи пул, потім стабілізуй +6–+9, а вже після цього спокійно йди в push на +10 і вище**.  \nСаме так Season 1 проходиться значно приємніше й без зайвого “чому цей пак знову нас розібрав”.","author":"Sebas","date":"2026-03-16","last_modified_at":"2026-03-16","categories":"Гайди, Mythic+","tags":"Midnight, Mythic+, Season 1, Keystone Master, Dungeons","image":"/assets/img-content/Season-1.webp","revision":1,"updated_at":"2026-10-15T00:00:00.000Z"}'::jsonb) ON CONFLICT (collection,doc_id) DO NOTHING;
INSERT INTO documents(collection,doc_id,data) VALUES ('siteArticles','guides:midnight-class-tier-list-updated-guide','{"kind":"guides","slug":"midnight-class-tier-list-updated-guide","title":"Midnight Class Tier List — оновлений гайд Season 1","description":"Оновлений і зрозумілий гайд по спеціалізаціях у World of Warcraft: Midnight Season 1: актуальна мета для рейдів і Mythic+, зведений tier list і практичні рекомендації.","body":"На старті **Midnight Season 1** немає одного-єдиного “правильного” tier list для всього одразу.  \nУ **рейді** й **Mythic+** цінуються різні речі: десь важливіші raid utility і стабільний single target, десь — контроль паків, живучість і burst у потрібний момент.\n\nТому нижче — не “магічна таблиця на всі випадки життя”, а **нормальний зведений гайд**, який допоможе швидко зрозуміти:\n- хто зараз реально сильний\n- кого комфортно брати в Season 1\n- які спеки виглядають найнадійніше для рейду і Mythic+\n- це сугубл моя думка і непотрібно брати все це як істину\n---\n\n## Швидкий висновок\n\nЯкщо тобі потрібна зовсім коротка відповідь, то зараз найнадійнішими виборами виглядають:\n\n- **Demonology Warlock**\n- **Feral Druid**\n- **Elemental Shaman**\n- **Restoration Druid**\n- **Preservation Evoker**\n- **Brewmaster Monk**\n\nЦе ті спеки, які або вже стоять дуже високо у своїй ролі, або стабільно виглядають добре відразу в найактуальнішому PvE-контенті.\n\n---\n\n## Зведений tier list\n\n> Це **зведений** рейтинг для старту Season 1, а не офіційна таблиця Blizzard.  \n> Він побудований на поточних рейтингах для рейду, Mythic+ і загальної “цінності мейна” для ключів.\n\n| Тир | Спеціалізації |\n|---|---|\n| **S** | Demonology Warlock, Feral Druid, Elemental Shaman, Restoration Druid, Preservation Evoker, Brewmaster Monk |\n| **A** | Arcane Mage, Unholy Death Knight, Enhancement Shaman, Survival Hunter, Devourer Demon Hunter, Holy Paladin, Guardian Druid, Protection Warrior, Vengeance Demon Hunter |\n| **B** | Shadow Priest, Fury Warrior, Frost Mage, Balance Druid, Devastation Evoker, Mistweaver Monk, Restoration Shaman, Protection Paladin, Affliction Warlock, Destruction Warlock, Augmentation Evoker, Blood Death Knight, Holy Priest, Havoc Demon Hunter |\n| **C** | Beast Mastery Hunter, Marksmanship Hunter, Subtlety Rogue, Outlaw Rogue, Assassination Rogue, Windwalker Monk, Retribution Paladin, Arms Warrior, Frost Death Knight, Discipline Priest |\n| **D** | Fire Mage |\n\n---\n\n## Найкращі DPS зараз\n\n### Найсильніші DPS для загального PvE\n\nНа старті сезону я б дивився насамперед на ці спеки:\n\n- **Demonology Warlock**\n- **Feral Druid**\n- **Elemental Shaman**\n- **Arcane Mage**\n- **Unholy Death Knight**\n\n### Demonology Warlock\n\n**Demonology Warlock** зараз виглядає одним із найстабільніших і найсильніших DPS-спеків сезону.  \nУ нього сильний тиск по цілях, хороший урон у паках і дуже корисний набір утиліти.\n\nКлючові здібності:\n- <a href=\"https://www.wowhead.com/spell=265187/summon-demonic-tyrant\" data-wowhead=\"spell=265187\">Summon Demonic Tyrant</a>\n- <a href=\"https://www.wowhead.com/spell=105174/hand-of-guldan\" data-wowhead=\"spell=105174\">Hand of Gul''dan</a>\n- <a href=\"https://www.wowhead.com/spell=196277/implosion\" data-wowhead=\"spell=196277\">Implosion</a>\n\nЧому він такий сильний:\n- високий загальний урон\n- сильна утиліта\n- дуже комфортно почувається в Mythic+\n- добре виглядає і в рейді\n\n### Feral Druid\n\n**Feral Druid** зараз дуже сильний, особливо в рейдовому контенті.  \nПісля змін спек став зручнішим, а його burst і тиск через bleed-ефекти лишилися дуже небезпечними.\n\nКлючові здібності:\n- <a href=\"https://www.wowhead.com/spell=1822/rake\" data-wowhead=\"spell=1822\">Rake</a>\n- <a href=\"https://www.wowhead.com/spell=285381/primal-wrath\" data-wowhead=\"spell=285381\">Primal Wrath</a>\n- <a href=\"https://www.wowhead.com/spell=22568/ferocious-bite\" data-wowhead=\"spell=22568\">Ferocious Bite</a>\n\n### Elemental Shaman\n\n**Elemental Shaman** зараз стоїть значно вище, ніж багато хто очікував перед релізом.  \nВін дуже добре почувається в Mythic+ і водночас високо стоїть у рейдових DPS-списках.\n\nКлючові здібності:\n- <a href=\"https://www.wowhead.com/spell=188389/flame-shock\" data-wowhead=\"spell=188389\">Flame Shock</a>\n- <a href=\"https://www.wowhead.com/spell=117014/elemental-blast\" data-wowhead=\"spell=117014\">Elemental Blast</a>\n- <a href=\"https://www.wowhead.com/spell=61882/earthquake\" data-wowhead=\"spell=61882\">Earthquake</a>\n\n### Arcane Mage\n\n**Arcane Mage** вже не виглядає “єдиним королем усього”, але все ще лишається дуже сильним вибором.  \nЯкщо ти вмієш добре натискати кнопки, він досі може розривати пріоритетні цілі.\n\nКлючові здібності:\n- <a href=\"https://www.wowhead.com/spell=44425/arcane-barrage\" data-wowhead=\"spell=44425\">Arcane Barrage</a>\n- <a href=\"https://www.wowhead.com/spell=321507/touch-of-the-magi\" data-wowhead=\"spell=321507\">Touch of the Magi</a>\n- <a href=\"https://www.wowhead.com/spell=365350/arcane-surge\" data-wowhead=\"spell=365350\">Arcane Surge</a>\n\n### Unholy Death Knight\n\n**Unholy DK** лишається дуже сильним melee-вибором для Mythic+.  \nЙого цінують за burst-вікна, сильний тиск у паках і хорошу витривалість.\n\nКлючові здібності:\n- <a href=\"https://www.wowhead.com/spell=42650/army-of-the-dead\" data-wowhead=\"spell=42650\">Army of the Dead</a>\n- <a href=\"https://www.wowhead.com/spell=207289/unholy-assault\" data-wowhead=\"spell=207289\">Unholy Assault</a>\n- <a href=\"https://www.wowhead.com/spell=47541/death-coil\" data-wowhead=\"spell=47541\">Death Coil</a>\n\n---\n\n## Найкращі хіли зараз\n\n### Mythic+\nДля Mythic+ найкраще зараз виглядає:\n- **Restoration Druid**\n\nСильні альтернативи:\n- **Mistweaver Monk**\n- **Holy Paladin**\n- **Restoration Shaman**\n\n### Рейд\nДля рейду особливо цінуються:\n- **Preservation Evoker**\n- **Restoration Druid**\n- **Holy Paladin**\n\n### Restoration Druid\n\n**Restoration Druid** зараз виглядає найсильнішим healer-ом для Mythic+.  \nУ нього дуже хороша загальна стабільність, сильне відновлення групи й зручний темп гри.\n\nКлючові здібності:\n- <a href=\"https://www.wowhead.com/spell=774/rejuvenation\" data-wowhead=\"spell=774\">Rejuvenation</a>\n- <a href=\"https://www.wowhead.com/spell=48438/wild-growth\" data-wowhead=\"spell=48438\">Wild Growth</a>\n- <a href=\"https://www.wowhead.com/spell=740/tranquility\" data-wowhead=\"spell=740\">Tranquility</a>\n\n### Preservation Evoker\n\n**Preservation Evoker** зараз особливо сильний у рейді.  \nЙого дуже цінують за унікальний utility-пакет і сильне масове відновлення здоров’я.\n\nКлючові здібності:\n- <a href=\"https://www.wowhead.com/spell=361469/rewind\" data-wowhead=\"spell=361469\">Rewind</a>\n- <a href=\"https://www.wowhead.com/spell=370665/rescue\" data-wowhead=\"spell=370665\">Rescue</a>\n- <a href=\"https://www.wowhead.com/spell=374227/zephyr\" data-wowhead=\"spell=374227\">Zephyr</a>\n\n### Holy Paladin\n\n**Holy Paladin** усе ще лишається дуже сильним і надійним хілом.  \nВін особливо хороший для тих, хто любить кнопки порятунку й хоче відчувати, що реально може “витягнути” кризовий момент.\n\nКлючові здібності:\n- <a href=\"https://www.wowhead.com/spell=20473/holy-shock\" data-wowhead=\"spell=20473\">Holy Shock</a>\n- <a href=\"https://www.wowhead.com/spell=633/lay-on-hands\" data-wowhead=\"spell=633\">Lay on Hands</a>\n- <a href=\"https://www.wowhead.com/spell=1022/blessing-of-protection\" data-wowhead=\"spell=1022\">Blessing of Protection</a>\n\n---\n\n## Найкращі танки зараз\n\n### Mythic+\nУ ключах зараз найкраще виглядає:\n- **Brewmaster Monk**\n\nСильні альтернативи:\n- **Protection Warrior**\n- **Vengeance Demon Hunter**\n- **Protection Paladin**\n\n### Рейд\nУ рейді найкраще виглядають:\n- **Guardian Druid**\n- **Brewmaster Monk**\n- **Protection Warrior**\n\n### Brewmaster Monk\n\n**Brewmaster Monk** зараз — один із найкращих танків сезону.  \nВін дуже добре переживає важкі pull-и, має сильний урон і почувається дуже впевнено в Mythic+.\n\nКлючові здібності:\n- <a href=\"https://www.wowhead.com/spell=124255/stagger\" data-wowhead=\"spell=124255\">Stagger</a>\n- <a href=\"https://www.wowhead.com/spell=119582/purifying-brew\" data-wowhead=\"spell=119582\">Purifying Brew</a>\n- <a href=\"https://www.wowhead.com/spell=243435/fortifying-brew\" data-wowhead=\"spell=243435\">Fortifying Brew</a>\n\n### Guardian Druid\n\n**Guardian Druid** дуже сильний у рейдовому контенті, а ще й досі лишається зручним і дружнім танком для багатьох гравців.\n\nКлючові здібності:\n- <a href=\"https://www.wowhead.com/spell=22842/frenzied-regeneration\" data-wowhead=\"spell=22842\">Frenzied Regeneration</a>\n- <a href=\"https://www.wowhead.com/spell=192081/ironfur\" data-wowhead=\"spell=192081\">Ironfur</a>\n- <a href=\"https://www.wowhead.com/spell=61336/survival-instincts\" data-wowhead=\"spell=61336\">Survival Instincts</a>\n\n### Protection Warrior\n\n**Protection Warrior** зараз виглядає дуже солідно, особливо якщо тобі потрібен танк, який хороший і сам по собі, і як джерело корисного raid utility.\n\nКлючові здібності:\n- <a href=\"https://www.wowhead.com/spell=190456/ignore-pain\" data-wowhead=\"spell=190456\">Ignore Pain</a>\n- <a href=\"https://www.wowhead.com/spell=23922/shield-slam\" data-wowhead=\"spell=23922\">Shield Slam</a>\n- <a href=\"https://www.wowhead.com/spell=871/shield-wall\" data-wowhead=\"spell=871\">Shield Wall</a>\n\n---\n\n## Якщо обирати мейна прямо зараз\n\nОсь найпростіший орієнтир:\n\n- хочеш **найстабільнішого DPS** — **Demonology Warlock**\n- хочеш **дуже сильного melee** — **Feral Druid** або **Unholy Death Knight**\n- хочеш **сильного caster без відчуття, що ти промахнувся класом** — **Elemental Shaman**\n- хочеш **найнадійнішого healer-а для ключів** — **Restoration Druid**\n- хочеш **дуже цінного raid healer-а** — **Preservation Evoker**\n- хочеш **найкращий старт серед танків** — **Brewmaster Monk**\n- хочеш **більш простий і дружній tank-вибір** — **Guardian Druid**\n\n---\n\n## Підсумок\n\nНа старті **Midnight Season 1** я б не радив орієнтуватися на старі “універсальні” tier list, де один і той самий спек оголошують найкращим всюди й одразу.\n\nНабагато корисніше мислити так:\n\n- **для Mythic+** зараз особливо хороші **Demonology Warlock**, **Elemental Shaman**, **Restoration Druid** і **Brewmaster Monk**\n- **для рейду** дуже сильні **Feral Druid**, **Demonology Warlock**, **Elemental Shaman**, **Preservation Evoker**, **Guardian Druid**, **Brewmaster Monk** і **Protection Warrior**\n- якщо хочеш один із найнадійніших мейнів на старті сезону, то найкращі ставки зараз — **Demo Lock**, **Ele Shaman**, **Resto Druid**, **Pres Evoker** або **Brewmaster Monk**\n\nА далі вже обирай не лише за цифрами, а й за тим, чи тобі реально подобається спек.  \nБо навіть найвищий тир не допоможе, якщо персонаж дратує тебе сильніше, ніж пак кастерів без interrupt-ів.","author":"Дмитро [Khayen, Krouli]","date":"2026-03-17","last_modified_at":"2026-05-21","categories":"Гайди, Класи","tags":"Midnight, Class Tier List, Season 1, DPS, Healer, Tank, Mythic+, Raid","image":"/assets/img-content/best-classes-in-wow-midnight.webp","revision":1,"updated_at":"2026-10-15T00:00:00.000Z"}'::jsonb) ON CONFLICT (collection,doc_id) DO NOTHING;
INSERT INTO documents(collection,doc_id,data) VALUES ('siteArticles','guides:alchemy-in-midnight-short-guide','{"kind":"guides","slug":"alchemy-in-midnight-short-guide","title":"Alchemy in Midnight — короткий гайд","description":"Короткий і зрозумілий гайд по Alchemy у World of Warcraft: Midnight: які стати качати, яке спорядження брати і що робити для крафту та заробітку.","body":"Якщо коротко, **Alchemy у Midnight** зараз дуже зручна професія для двох речей:\n\n- крафту **потів, фласок, фіалів і реагентів**\n- стабільного заробітку через **масовий крафт** і **трансмути**\n\nГоловна ідея проста: для більшості алхімічного крафту ти хочеш **Multicraft**, а далі вже добираєш **Ingenuity** або **Resourcefulness** залежно від того, що саме крафтиш.\n\n---\n\n## Які стати качати\n\n### Базовий пріоритет\nДля Alchemy найкращий стартовий пріоритет такий:\n\n1. **Multicraft**\n2. **Ingenuity**\n\nСаме ця зв’язка найкраще працює для масового крафту:\n- потів\n- фласок\n- професійних фіалів\n- реагентів\n- частини трансмутів\n\n### Коли міняти Ingenuity\nКоли в тебе вже:\n- високий рівень професії\n- хороше спорядження\n- нормально розкачані таланти\n\nі ти **вже можеш стабільно крафтити максимальний ранг з найкращих матеріалів**, тоді **Ingenuity** втрачає частину цінності.\n\nУ цей момент є два нормальні варіанти:\n\n- міняти частину **Ingenuity** на **Resourcefulness**\n- або крафтити з матеріалів нижчого рангу через **Concentration**\n\n### Просте правило\n- якщо рецепт **може Multicraft** — бери **Multicraft**\n- якщо рецепт **не може Multicraft** — цінність **Resourcefulness** росте дуже сильно\n\n> Для звичайного алхіміка, який крафтить банки й витратники, **Multicraft** майже завжди буде найкращим другом. Ingenuity — хороший друг на старті. Resourcefulness — друг на пізнішому етапі й для частини трансмутів.\n\n---\n\n## Найкраще спорядження для Alchemy\n\nАлхімік може носити **3 предмети професійного спорядження**:\n\n- **1 інструмент**\n- **2 аксесуари**\n\n### Найкращий набір\n- <a href=\"https://www.wowhead.com/spell=1264550\" data-wowhead=\"spell=1264550\">Gilded Alchemist''s Mixing Rod</a>\n- <a href=\"https://www.wowhead.com/spell=1279123\" data-wowhead=\"spell=1279123\">Thalassian Alchemy Coveralls</a>\n- <a href=\"https://www.wowhead.com/spell=1237550\" data-wowhead=\"spell=1237550\">Thalassian Alchemist''s Mixcap</a>\n\n### Що брати на старті\nЯкщо золота або ресурсів небагато, починай із зеленого спорядження:\n- **Hobbyist Alchemist''s Mixing Rod**\n- **Chemist''s Cap**\n- **Bright Linen Alchemy Apron**\n\nПотім переходь на blue/epic.\n\n### Що апгрейдити першим\nЯкщо апгрейди робиш поступово, **спочатку покращуй Mixing Rod**, а вже потім аксесуари.\n\n### Важливо\n- **зелені** версії зазвичай простіше взяти\n- **сині та епічні** часто йдуть через **Crafting Order**\n- частина сильніших рецептів спорядження або енчантів зав’язана на **renown** чи спеціалізації\n\n---\n\n## Що обов’язково використати\n\n### Енчант на інструмент\nНа Mixing Rod майже завжди варто ставити:\n\n- <a href=\"https://www.wowhead.com/item=243994\" data-wowhead=\"item=243994\">Enchant Tool - Haranir Multicrafting</a>\n\nДля більшості алхіміків це найкращий універсальний варіант.\n\n### Професійний фіал\nДля тимчасового буста крафту дуже корисний:\n\n- <a href=\"https://www.wowhead.com/item=241312/haranir-phial-of-ingenuity\" data-wowhead=\"item=241312\">Haranir Phial of Ingenuity</a>\n\nВін особливо хороший, коли тобі треба дотиснути дорогий або важливий крафт.\n\n### Опціональні реагенти\nДля дорогих крафтів варто дивитися на:\n- **Multicraft Matrix**\n- **Multicraft Manifold**\n- **Mentor''s Helpful Handiwork**\n\nПростою мовою:\n- **Matrix / Manifold** — коли хочеш вичавити більше користі з Multicraft\n- **Mentor''s Helpful Handiwork** — коли треба сильніше дотиснути результат за скілом\n\n---\n\n## Що корисно крафтити\n\n### Для себе\n- <a href=\"https://www.wowhead.com/spell=1230869\" data-wowhead=\"spell=1230869\">Light''s Potential</a>\n- <a href=\"https://www.wowhead.com/spell=1230865\" data-wowhead=\"spell=1230865\">Lightfused Mana Potion</a>\n- <a href=\"https://www.wowhead.com/spell=1230859\" data-wowhead=\"spell=1230859\">Potion of Recklessness</a>\n- <a href=\"https://www.wowhead.com/spell=1230864\" data-wowhead=\"spell=1230864\">Amani Extract</a>\n\n### Для професій\nУ Midnight є окремі **phials** саме для професійних статів, а не тільки бойові витратники.  \nНаприклад:\n- <a href=\"https://www.wowhead.com/item=241312/haranir-phial-of-ingenuity\" data-wowhead=\"item=241312\">Haranir Phial of Ingenuity</a>\n- <a href=\"https://www.wowhead.com/spell=1230873\" data-wowhead=\"spell=1230873\">Haranir Phial of Perception</a>\n\nЦе важливий момент, бо фіали в Midnight — не просто “ще одна фласка”, а окремий інструмент для професій.\n\n---\n\n## Короткі поради по Alchemy in Midnight\n\n### 1. Не пропускай перші крафти\nПерші крафти дають дуже багато користі на старті. Через них ти швидше піднімаєш професію й відкриваєш нормальний темп прогресу.\n\n### 2. До 30 — вчиш базу, після 30 — прискорюєшся\nНайпростіша логіка така:\n- стартуєш із trainer crafts і first-craft бонусів\n- доходиш приблизно до **30**\n- далі дуже зручно масово крафтити **Light''s Potential**\n\nЦе один із найпростіших способів швидко качнути професію в Midnight.\n\n### 3. Обов’язково користуйся recycle\nНе викидай зайве.  \nУ Midnight Alchemy дуже важливо **переробляти непотрібні крафти**, бо так ти отримуєш ресурси назад і допомагаєш собі з подальшим прогресом.\n\n### 4. Якщо не знаєш, у що вкладати Knowledge\nНайпростіший орієнтир такий:\n\n- хочеш банки й стабільний попит — **Potion Prowess**\n- хочеш фласки / фіали — **Fluent in Flasks**\n- хочеш заробляти на трансмутах — **Transmutation Authority**\n- хочеш універсальний фундамент — **Alchemical Mastery**\n\nЯкщо ти поки не впевнений, що саме будеш крафтити постійно, **Alchemical Mastery** — найменш ризиковий старт.\n\n### 5. Для рейду й M+ дуже зручний шлях через Flasks\nЯкщо твоя мета — не тільки продаж, а ще й гра на персонажі, то вкладення у **Fluent in Flasks** виглядає дуже практично.\n\n### 6. Для AH не розпилюйся одразу на все\nНайпоширеніша помилка — качати потроху все.  \nНабагато вигідніше спочатку **вибрати одну лінійку**:\n- або potions\n- або flasks\n- або phials\n\nі вже потім розгалужуватися.\n\n### 7. Трансмути тепер цікавіші\nУ Midnight частина трансмутів тепер теж працює з **Multicraft**, а це робить їх значно приємнішими для заробітку, ніж раніше.\n\n### 8. Збирай Knowledge Points регулярно\nДля Alchemy дуже важливо не випадати з тижневого прогресу.  \nСлідкуй за:\n- **Patron Crafting Orders**\n- тижневими квестами / замовленнями\n- **Treatise**\n- treasure drops\n- one-time treasure pickups\n\nОкремо в Midnight для Alchemy є ще **8 скарбів**, які дають **24 one-time Knowledge Points**, а також разова книжка на **10 KP** у renown-продавця.\n\n---\n\n## Найпростіша схема для більшості гравців\n\nЯкщо не хочеш заморочуватися, роби так:\n\n1. качаєш Alchemy через trainer crafts і first-craft бонуси\n2. після цього переходиш у масовий крафт <a href=\"https://www.wowhead.com/spell=1230869\" data-wowhead=\"spell=1230869\">Light''s Potential</a>\n3. носиш **Multicraft**-спорядження\n4. ставиш <a href=\"https://www.wowhead.com/item=243994\" data-wowhead=\"item=243994\">Enchant Tool - Haranir Multicrafting</a>\n5. використовуєш <a href=\"https://www.wowhead.com/item=241312/haranir-phial-of-ingenuity\" data-wowhead=\"item=241312\">Haranir Phial of Ingenuity</a> на важливих крафтах\n6. не пропускаєш weekly Knowledge\n7. коли вже впираєшся в кап якості — частково переходиш у **Resourcefulness**\n\n---\n\n## Підсумок\n\nДля **Alchemy in Midnight** найпростіша й найнадійніша логіка така:\n\n- **на старті:** Multicraft + Ingenuity\n- **після капу якості:** Multicraft + Resourcefulness\n- **найкраще спорядження:** Mixing Rod + Coveralls + Mixcap\n- **must-have:** енчант на Multicraft і професійний фіал\n- **для золота:** вибирай одну лінійку крафту і качай її глибоко\n- **для прогресу:** не пропускай recycle, Knowledge і treasure pickups\n\nЯкщо коротко зовсім по-людськи:  \n**Alchemy у Midnight любить тих, хто не хаотично варить усе підряд, а чітко обирає напрям і качає його до кінця.**","author":"Sebas","date":"2026-03-22","last_modified_at":"2026-03-22","categories":"Гайди, Професії","tags":"Midnight, Alchemy, Crafting, Professions","image":"/assets/img/news-placeholder.webp","revision":1,"updated_at":"2026-10-15T00:00:00.000Z"}'::jsonb) ON CONFLICT (collection,doc_id) DO NOTHING;
